const proxy = require('express-http-proxy');

app.use('/telehealth/rooms/:roomId', verifyJwt, async (req, res, next) => {
  const { roomId } = req.params;
  const isParticipant = await db.query(
    'SELECT id FROM telehealth_room_participants WHERE room_id = $1 AND user_id = $2',
    [roomId, req.user.id]
  );
  if (isParticipant.rowCount === 0) {
    return res.status(403).json({ error: 'Access denied: you are not a participant in this consultation room' });
  }
  next();
}, proxy(process.env.WEBRTC_SIGNALING_SERVICE, {
  proxyReqPathResolver: (req) => {
    return `/internal/video/rooms/${req.params.roomId}${req.url}`;
  }
}));
